    PC.CPF_PESSOA CPF, 
    HN.NOME, 
    FS.NOME_SEXO SEXO,
    P.NOME_MAE,
    PEN.CEP, 
    PEN.LOGRADOURO,
    PEN.COMPLEMENTO_ENDERECO,
