    P.NOME_MAE,
    PEN.CEP, 
    PEN.LOGRADOURO,
    PEN.COMPLEMENTO_ENDERECO,
    PEN.BAIRRO_ENDERECO,
    PEN.NUMERO_ENDERECO,
    UF.COD_UNIDADE_FEDERACAO ENDERECO_UF,
    PEN.CIDADE_CIDADE,
    '' FONE_RESIDENCIAL,
    P.DDD,
