    CCF.COD_CATEGORIA_FUNCIONAL,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA,
    NULL NOME_ORGAO,
    UF.NOME_UNIDADE_FEDERACAO NOME_UNIDADE,
    L.NOME_LOTACAO NOME_LOTACAO, 
    '' IDENTIFICADOR_CARGO,
