SELECT 
    'SW_SIA' ORGAO,
    FO.CHAVE_FOLHA,
    FO.MES,
    FO.ANO,
    FF.COD_INSTITUCIONAL MATRICULA,
    PC.CPF_PESSOA CPF, 
    HN.NOME, 
    FS.NOME_SEXO SEXO,
    P.NOME_MAE,
    PEN.CEP, 
    PEN.LOGRADOURO,
    PEN.COMPLEMENTO_ENDERECO,
    PEN.BAIRRO_ENDERECO,
    PEN.NUMERO_ENDERECO,
    UF.COD_UNIDADE_FEDERACAO ENDERECO_UF,
    PEN.CIDADE_CIDADE,
    '' FONE_RESIDENCIAL,
    P.DDD,
    P.CELULAR,
    '' FONE_LOCAL_TRABALHO,
    PEM.EMAIL, 
    P.EMAIL_ALTERNATIVO,
    P.NOME_PAI,
    IPEC.NOME_ESTADO_CIVIL,
    IE.NOME_ESCOLARIDADE,
    CASE
        WHEN CF.IND_CAPACIDADE_TRABALHO = 'N' THEN 'N'
        WHEN CF.IND_CAPACIDADE_TRABALHO = 'S' THEN 'S'
        ELSE NULL 
    END PORTADOR_DOENCA_INCAPACITANTE,
    CF.DATA_CADASTRO DATA_INICIO_DOENCA,
    '' DATA_FIM_DOENCA_INCAPACITANTE,
    CASE
        WHEN CF.ENFERMIDADE IS NOT NULL THEN 'S'
        WHEN CF.ENFERMIDADE IS NULL THEN 'N'
    END PORTADOR_DE_MOLESTIA_GRAVE,
    CF.DATA_CADASTRO  DATA_INICIO_MOLESTIA,
    '' DATA_FIM_MOLESTIA,
    NAC.NOME_NACIONALIDADE,
    UF1.COD_UNIDADE_FEDERACAO NATURALIDADE_UF,
    CMI.NOME_MUNICIPIO NATURALIDADE_CIDADE,
    PDP.PISPASEP PIS_PASEP, 
    IC.NUMERO_CARTEIRA_IDENTIDADE RG_NUMERO,
    ED.SIGLA_ORGAO_EXPEDICAO_DOCUMENT RG_ORGAO,
    UF2.COD_UNIDADE_FEDERACAO RG_UF,
    IC.DATA_EXPEDICAO RG_DATA_EXPEDICAO,
    CT.CARTEIRA_TRABALHO CTPS_NUMERO,
    CT.SERIE_CARTEIRA_TRABALHO CTPS_SERIE,
    UF3.COD_UNIDADE_FEDERACAO CTPS_UF,
    CT.DATA_EXPEDICAO CTPS_DATA_EMISSAO,
    CT.DATA_EXPEDICAO CTPS_DATA_EXPEDICAO,
    '' LOCAL_EXPEDICAO,
    TE.NUMERO_TITULO_ELEITOR,
    TE.ZONA_TITULO_ELEITOR,
    TE.SECAO_TITULO_ELEITOR,
    UF4.COD_UNIDADE_FEDERACAO TITULO_ELEITOR_UF,
    FF.COD_INSTITUCIONAL IDENTIFICADOR_SEGURADO,
    FF.COD_INSTITUCIONAL COD_MATRICULA_SEGURADO,
    CCF.COD_CATEGORIA_FUNCIONAL,
    CCF.DESCRICAO_CATEGORIA_FUNCIONAL DESCRICAO_CATEGORIA,
    NULL NOME_ORGAO,
    UF.NOME_UNIDADE_FEDERACAO NOME_UNIDADE,
    L.NOME_LOTACAO NOME_LOTACAO, 
    '' IDENTIFICADOR_CARGO,
    CCF.NOME_CATEGORIA_FUNCIONAL NOME_CARGO,
    FI.DATA_POSSE DATA_ADMISSAO, 
    '' IDENTIFICADOR_FONTE_PAGADORA,
    '' NOME_FONTE_PAGADORA,
    PS.NOME_SITUACAO TIPO_SITUACAO_FUNCIONAL,
    FP.DATA_INICIO DATA_SITUACAO_FUNCIONAL,
    CASE
        WHEN FD.ID_FUNCIONARIO IS NOT NULL THEN 'S'
        --ELSE 'N'
    END EXCLUIDO_EXONERADO,
    FD.DATA_DESLIGAMENTO DATA_SAIDA,
    EMD.DESCRICAO MOTIVO_EXCLUSAO_SAIDA,
    CASE 
        WHEN FIG.IND_ESOCIAL_REG_PREV = 'V1' THEN 'Regime Geral da Previdência Social - RGPS'
        WHEN FIG.IND_ESOCIAL_REG_PREV = 'V2' THEN 'Regime Próprio de Previdência Social - RPPS'
        WHEN FIG.IND_ESOCIAL_REG_PREV = 'V3' THEN 'Regime de Previdência Social no Exterior'
    END FUNDO_PREVIDENCIARIO,
    CASE 
        WHEN IP_ABONO.ID_FUNCIONARIO IS NOT NULL THEN 'S'
        ELSE 'N'
    END ABONO_PERMANENCIA,
    IP_ABONO.DATA_INICIO DATA_ABONO_PERMANENCIA
FROM 
    SW_SIA.FOLHA FO
    JOIN SW_SIA.FOLHA_FUNC FF ON FF.ID_FOLHA = FO.ID_FOLHA
    LEFT JOIN (
    SELECT 
        IP.ID_FUNCIONARIO,
        IP.DATA_INICIO,
        ROW_NUMBER() OVER (
            PARTITION BY IP.ID_FUNCIONARIO 
            ORDER BY IP.DATA_INICIO DESC
        ) RN
    FROM SW_SIA.FUNCIONARIO_INF_PARAMETRIZADA IP
    WHERE IP.ID_PARAMETRO = 555661
      AND IP.DATA_FIM IS NULL   -- pega só o abono ativo (sem data de término)
) IP_ABONO ON IP_ABONO.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND IP_ABONO.RN = 1
    LEFT JOIN SW_SIA.FUNCIONARIO_REFERENCIA FR ON FR.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FR.DATA_TERMINO IS NULL
    LEFT JOIN SW_SIA.FUNCIONARIO_INGRESSO FI ON FI.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FI.DATA_TERMINO IS NULL
    LEFT JOIN SW_SIA.RHB_CARREIRA_CATEG_FUNCIONAL CCF ON CCF.ID_CATEGORIA_FUNCIONAL = NVL(FR.ID_CATEGORIA_FUNCIONAL, FI.ID_CATEGORIA_FUNCIONAL)
    LEFT JOIN SW_SIA.FUNCIONARIO_PERFIL FP ON FP.ID_FUNCIONARIO = FF.ID_FUNCIONARIO AND FP.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL RP ON RP.ID_PERFIL = FP.ID_PERFIL
    LEFT JOIN SW_PUBLICO.RHB_PERFIL_SITUACAO PS ON PS.ID_SITUACAO = RP.ID_SITUACAO
    LEFT JOIN SW_PUBLICO.PESSOA P ON P.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND P.DATA_OBITO IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_HISTORICO_NOMES HN ON HN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND HN.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CPF PC ON PC.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO AND PC.DATA_BAIXA IS NULL
    LEFT JOIN SW_PUBLICO.PESSOA_EMAIL PEM ON PEM.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.PESSOA_ENDERECO PEN ON PEN.ID_PESSOA = FF.ID_PESSOA_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.RHB_CARACT_FISICA_SEXO FS ON FS.ID_SEXO = P.ID_SEXO
    LEFT JOIN SW_PUBLICO.RHB_CEP_UNIDADE_FEDERACAO UF ON UF.ID_UNIDADE_FEDERACAO = PEN.ID_UNIDADE_FEDERACAO 
    LEFT JOIN SW_PUBLICO.PESSOA_ESTADO_CIVIL PEC ON PEC.ID_PESSOA = P.ID_PESSOA AND PEC.DATA_FIM IS NULL
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_ESTADO_CIVIL IPEC ON IPEC.ID_ESTADO_CIVIL = PEC.ID_ESTADO_CIVIL
    LEFT JOIN SW_PUBLICO.RHB_INSTRUCAO_ESCOLARIDADE IE ON IE.ID_ESCOLARIDADE = P.ID_ESCOLARIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_CARACTERISTICA_FISICA CF ON CF.ID_PESSOA = P.ID_PESSOA
    LEFT JOIN SW_PUBLICO.RHB_INF_PESSOAL_NACIONALIDADE NAC ON NAC.ID_NACIONALIDADE = P.ID_NACIONALIDADE
    LEFT JOIN SW_PUBLICO.RHB_CEP_UNIDADE_FEDERACAO UF1 ON UF1.ID_UNIDADE_FEDERACAO = P.ID_UNIDADE_FEDERAC_NASCIMENTO
    LEFT JOIN SW_PUBLICO.RHB_CEP_MUNICIPIO_IBGE CMI ON CMI.ID_MUNICIPIO = P.ID_MUNICIPIO_NATURALIDADE
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_IDENTIDADE_CIVIL IC ON IC.ID_PESSOA = P.ID_PESSOA AND IC.DATA_CANCELAMENTO IS NULL
    LEFT JOIN SW_PUBLICO.RHB_ORGAO_EXPEDICAO_DOCUMENTO ED ON ED.ID_ORGAO_EXPEDICAO_DOCUMENTO = IC.ID_ORGAO_EXPEDICAO_DOCUMENTO
    LEFT JOIN SW_PUBLICO.RHB_CEP_UNIDADE_FEDERACAO UF2 ON UF2.ID_UNIDADE_FEDERACAO = IC.ID_UNIDADE_FEDERACAO
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_CARTEIRA_TRABALHO CT ON CT.ID_PESSOA = P.ID_PESSOA AND CT.DATA_BAIXA IS NULL
    LEFT JOIN SW_PUBLICO.RHB_CEP_UNIDADE_FEDERACAO UF3 ON UF3.ID_UNIDADE_FEDERACAO = CT.ID_UNIDADE_FEDERACAO
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_TITULO_ELEITORAL TE ON TE.ID_PESSOA = P.ID_PESSOA
    LEFT JOIN SW_PUBLICO.RHB_CEP_UNIDADE_FEDERACAO UF4 ON UF4.ID_UNIDADE_FEDERACAO = TE.ID_UNIDADE_FEDERACAO
    LEFT JOIN SW_SIA.FUNC_DESLIGAMENTO FD ON FD.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_PUBLICO.ESB_MOTIVOS_DESLIGAMENTO EMD ON EMD.ID_ESB_MOTIVOS_DESLIGAMENTO = FD.ID_ESOCIAL_MOTIVO_DESLIGAMENTO
    LEFT JOIN SW_SIA.FUNCIONARIO_INF_GOVERNO FIG ON FIG.ID_FUNCIONARIO = FF.ID_FUNCIONARIO
    LEFT JOIN SW_SIA.FUNC_LOTACAO FL ON FL.ID_FUNCIONARIO = FF.ID_FUNCIONARIO 
    LEFT JOIN SW_SIA.RHB_LOTACAO L ON L.ID_LOTACAO = FL.ID_LOTACAO 
    LEFT JOIN SW_PUBLICO.PESSOA_DOC_PISPASEP PDP ON PDP.ID_PESSOA = P.ID_PESSOA
WHERE 
    --FO.MES = 7 
    FO.ANO = 2026 
    AND FF.COD_INSTITUCIONAL IN ('369206-0','353887-7','402429-0','355985-8','311297-7','369228-X','369224-8','376033-2','369380-5','353877-0','353883-4','355981-5','369215-9','356033-3','402323-4','369214-X','402409-5','402434-6','369218-3','353901-6','402356-X','402930-5','369222-1','369231-X','356037-6','369234-5','354350-1','311287-0','369213-2','353872-9','369220-5','369226-4','369230-2','356031-7','356032-5','108512-3','009328-9','369233-7','369225-6','402329-3','369221-3','353892-3','369232-9','356028-7','369229-9','311289-6','369217-5','369194-2','369223-0','369212-4','369210-8','353867-2','369211-6','369216-7','369219-1','355996-3','369208-6','369209-4','369256-6','369264-7','369261-2','369273-6','369269-8','355994-7','369263-9','311293-4','369248-5','402265-3','311299-3','369257-4','369252-3','369251-5','369279-5','353876-1','402506-7','353886-9','369277-9','369278-7','369258-2','369359-7','369249-3','354867-8','353898-2','402315-5','369275-2','311295-X','369253-1','353895-8','369381-3','369266-3','369360-X','369247-7','353869-9','369255-8','369271-0','369262-X','369276-X','369270-1','369272-8','369268-0','353897-4','369817-3','369267-1','369254-0','353871-X','369274-4','311296-9','311278-X','369260-4','355989-X','369265-5','402321-8','353882-6','402324-2','369280-9','354348-0','369259-X','355997-1','355999-8','369250-7','402934-8','355998-0','369357-X','353873-7','369350-3','311191-1','369339-2','369344-9','369352-0','402430-3','369356-2','355993-9','369346-5','369384-8','353888-5','369353-8','355982-3','369335-0','369358-9','353880-0','402326-9','369351-1','369334-1','353879-6','369347-3','369379-1','402330-7','369341-4','369343-X','353864-8','369340-6','369348-1','369336-8','369338-4','369354-6','369337-6','402363-3','369349-0','353868-X','353900-8','369294-9','402320-0','369370-8','355986-6','369364-3','356030-9','369316-3','369327-9','402511-3','355990-4','369372-4','311493-7','369325-2','369295-7','402316-1','108495-0','369369-4','369371-6','353870-2